#include "common/log.h"

#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

static const char  *g_component = "?";
static log_level_t  g_min       = LOG_INFO;
static data_src_t   g_src       = SRC_LIVE;

static const char *level_name(log_level_t l)
{
    switch (l) {
    case LOG_DEBUG: return "DEBUG";
    case LOG_INFO:  return "INFO";
    case LOG_WARN:  return "WARN";
    case LOG_ERROR: return "ERROR";
    case LOG_FATAL: return "FATAL";
    }
    return "?";
}

void log_init(const char *component, log_level_t min)
{
    g_component = component;
    g_min       = min;
    setvbuf(stdout, NULL, _IOLBF, 0);
}

void log_set_src(data_src_t src) { g_src = src; }
data_src_t log_get_src(void)     { return g_src; }

const char *log_src_name(data_src_t src)
{
    switch (src) {
    case SRC_LIVE:   return "live";
    case SRC_REPLAY: return "replay";
    case SRC_SYNTH:  return "synth";
    }
    return "unknown";
}

static void stamp(char *buf, size_t n)
{
    struct timespec ts;
    struct tm       tm;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0 ||
        gmtime_r(&ts.tv_sec, &tm) == NULL) {
        snprintf(buf, n, "----------T--:--:--.---Z");
        return;
    }
    size_t k = strftime(buf, n, "%Y-%m-%dT%H:%M:%S", &tm);
    snprintf(buf + k, n - k, ".%03ldZ", ts.tv_nsec / 1000000L);
}

void log_emit(log_level_t lvl, const char *fmt, ...)
{
    if (lvl < g_min) return;

    char ts[40];
    stamp(ts, sizeof ts);

    /* ts level component src pid — then the message. Greppable and column-stable. */
    printf("%s %-5s %-10s src=%-6s pid=%d ",
           ts, level_name(lvl), g_component, log_src_name(g_src), (int)getpid());

    va_list ap;
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);

    putchar('\n');
}

/* Resident set size in KiB, from /proc/self/statm field 2 (pages). */
static long rss_kib(void)
{
    FILE *f = fopen("/proc/self/statm", "re");
    if (f == NULL) return -1;
    long total = 0, res = 0;
    int  got = fscanf(f, "%ld %ld", &total, &res);
    (void)fclose(f);
    if (got != 2) return -1;
    long page_kib = sysconf(_SC_PAGESIZE) / 1024;
    return res * page_kib;
}

void log_heartbeat(uint64_t events, uint64_t drops)
{
    log_emit(LOG_INFO, "heartbeat rss_kib=%ld events=%llu drops=%llu",
             rss_kib(), (unsigned long long)events, (unsigned long long)drops);
}
#include "store/record.h"

/* CRC-32 (IEEE 802.3, reflected). Table built on first use — no static init cost in
 * the capture path. Replaced by a hardware CRC on the Pi only if it ever shows up in
 * a profile; do not optimize this before measuring (CLAUDE.md §7.6). */
static uint32_t g_table[256];
static int      g_ready;

static void build_table(void)
{
    for (uint32_t i = 0; i < 256u; i++) {
        uint32_t c = i;
        for (int k = 0; k < 8; k++)
            c = (c & 1u) ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);
        g_table[i] = c;
    }
    g_ready = 1;
}

uint32_t rec_crc32(const void *buf, uint32_t len)
{
    if (!g_ready) build_table();
    const uint8_t *p = (const uint8_t *)buf;
    uint32_t c = 0xFFFFFFFFu;
    for (uint32_t i = 0; i < len; i++)
        c = g_table[(c ^ p[i]) & 0xFFu] ^ (c >> 8);
    return c ^ 0xFFFFFFFFu;
}
#include "store/record.h"

#include <stdio.h>
#include <string.h>

int main(void)
{
    int failures = 0;

    /* Known-answer test: CRC-32/IEEE of "123456789" is 0xCBF43926. If this ever
     * changes, the on-disk format has silently changed with it. */
    const char *v = "123456789";
    uint32_t got = rec_crc32(v, (uint32_t)strlen(v));
    if (got != 0xCBF43926u) {
        fprintf(stderr, "  FAIL crc32(\"123456789\") = 0x%08X, want 0xCBF43926\n", got);
        failures++;
    }

    if (rec_crc32("", 0) != 0u) {
        fprintf(stderr, "  FAIL crc32 of empty input must be 0\n");
        failures++;
    }

    /* A single flipped bit must change the CRC — that is the entire reason a torn
     * record is detectable on recovery. */
    char a[] = "carwatch", b[] = "carwatci";
    if (rec_crc32(a, 8) == rec_crc32(b, 8)) {
        fprintf(stderr, "  FAIL crc32 collided on a one-bit difference\n");
        failures++;
    }

    return failures == 0 ? 0 : 1;
}
