#include "ipc/ring.h"
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <unistd.h>
#define N 5000000ull
static ring_t *R; static volatile int done; static unsigned long bad_depth;
static void *prod(void *a){(void)a; for(uint64_t i=0;i<N;){ring_slot_t s; memset(&s,0,sizeof s); s.seq=i; memcpy(s.data,&i,8); if(ring_push(R,&s)) i++;} return NULL;}
static void *obs(void *a){(void)a; while(!done){ size_t d=ring_depth(R); if(d>RING_CAPACITY) bad_depth++; } return NULL;}
static int cons(void){ uint64_t want=0; ring_slot_t o; int errs=0; while(want<N){ if(ring_pop(R,&o)){ uint64_t v; memcpy(&v,o.data,8); if(o.seq!=want||v!=want) errs++; want++; } } return errs; }
int main(int argc,char**argv){
  if(argc>1 && !strcmp(argv[1],"fork")){
    R=mmap(NULL,sizeof *R,PROT_READ|PROT_WRITE,MAP_SHARED|MAP_ANON,-1,0); if(R==MAP_FAILED){perror("mmap");return 1;}
    ring_init(R); pid_t p=fork(); if(p==0){prod(NULL); _exit(0);} int e=cons(); waitpid(p,NULL,0);
    printf("fork: errs=%d overruns(refusals)=%llu\n",e,(unsigned long long)ring_overruns(R)); return e!=0;
  }
  R=malloc(sizeof *R); ring_init(R); pthread_t a,b,c; pthread_create(&a,0,prod,0); pthread_create(&c,0,obs,0);
  int e=cons(); pthread_join(a,0); done=1; pthread_join(c,0);
  printf("threads: errs=%d refusals=%llu third-party depth>CAP observations=%lu\n",e,(unsigned long long)ring_overruns(R),bad_depth); return e!=0;
}

